//! 🪢️ A refused original projector retains every partial field until funded closure.
use super::*;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetainedWorkOutcome,RetirementDemand};
use semio_framework_value::native_encoding::{NativeEncodeConstructionRecipient,NativeEncodeRetirementRecipient,NativeEncodeWorkRecipient};
use std::cell::Cell;

struct Recipient<'a>{grant:RetainedCloneGrant,received:RetainedCloneProgress,armed:&'a Cell<bool>,deny:bool,refused:bool}
impl NativeEncodeConstructionRecipient for Recipient<'_>{
 fn submitted(&self)->RetainedCloneProgress{self.received}
 fn grant(&mut self,_:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{Ok(self.grant)}
 fn accept(&mut self,_:RetainedCloneGrant,progress:RetainedCloneProgress)->Result<(),ValueError>{self.received=self.received.checked_add(progress)?;if self.deny&&self.armed.get()&&!self.refused{self.refused=true;Err(ValueError::literal(ValueRefusalKind::Canceled,"original projection receipt refused"))}else{Ok(())}}
}
struct Work{remaining:u64,committed:u64}
impl NativeEncodeWorkRecipient for Work{
 fn admits(&mut self,_:u64,additional:u64)->Result<bool,ValueError>{Ok(additional<=self.remaining)}
 fn committed(&mut self,actual:u64)->Result<(),ValueError>{self.remaining=self.remaining.checked_sub(actual).ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"original projection work exhausted"))?;self.committed=self.committed.checked_add(actual).ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"original projection work overflow"))?;Ok(())}
}
fn partial(frame:&ProjectFrame,total:usize)->bool{
 let Some(DslValue::Object(root))=frame.value.as_ref()else{return false};let Some((_,DslValue::Array(rows)))=root.iter().find(|(key,_)|key=="checkpoints")else{return false};let Some(DslValue::Object(fields))=rows.first()else{return false};let Some((key,DslValue::String(message)))=fields.iter().find(|(key,_)|key=="message")else{return false};root.capacity()==2&&rows.capacity()==1&&fields.capacity()==5&&key.capacity()==key.len()&&!message.is_empty()&&message.len()<=total&&message.capacity()==total
}
#[test]
fn original_partial_projection_keeps_keys_values_and_backing_until_paid_close(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🪢️partial-projection/🔣️.json")).unwrap();let text=law["unit"].as_str().unwrap().repeat(law["repeat"].as_u64().unwrap()as usize);assert_eq!(text.len(),law["utf8Bytes"].as_u64().unwrap()as usize);let canonical=serde_json::json!({"value":text.as_str()});assert_eq!(serde_json::from_str::<serde_json::Value>(&serde_json::to_string(&canonical).unwrap()).unwrap(),canonical);
 for case in law["cases"].as_array().unwrap(){
  let deny=case.as_str().unwrap()=="receiptRefusal";let mut source=SpaceHistorySnapshot::default();source.checkpoints.push(SpaceCheckpoint{id:"checkpoint".into(),parent_id:None,message:text.clone(),authors:Vec::new(),timestamp:HybridLogicalTimestamp{actor:0,physical_ms:0,logical:0},members:Vec::new()});let original=source.clone();let grant=RetainedCloneGrant{maximum_items:10000,maximum_copy_bytes:1048576,maximum_capacity_bytes:4194304,maximum_release_bytes:4194304,maximum_depth:128};let armed=Cell::new(false);let live=Cell::new(true);let seen=Cell::new(false);let limit=law["cancelAfterBytes"].as_u64().unwrap()as usize;let mut observer=|event:semio_framework_value::native_encoding::NativeEncodeProgress|{if event.total==text.len()&&event.completed>=limit&&event.completed<event.total{armed.set(true);if !deny{live.set(false)}}live.get()};let mut retirement=NativeEncodeRetirementRecipient::new();let mut native=NativeEncodeControl::new(grant.maximum_capacity_bytes,&mut observer);native.install_retirement_recipient(&mut retirement).unwrap();let mut recipient=Recipient{grant,received:Default::default(),armed:&armed,deny,refused:false};let mut output=None;
  let mut work=Work{remaining:1000000,committed:0};let mut work_issuer=semio_framework_value::native_encoding::NativeEncodeWorkIssuer::new();let mut work_loan=work_issuer.loan(&mut work);let mut construction_issuer=semio_framework_value::native_encoding::NativeEncodeConstructionIssuer::new();let reported=Cell::new(0);
  native.with_work_recipient(&mut work_loan,|native|{
   let (turn,born,released)=semio_framework_trace_memory_testing::observe_backing(||{let mut construction_loan=construction_issuer.loan(&mut recipient);native.with_construction_recipient(&mut construction_loan,|native|{let mut owner=semio_framework_io_control::NativeSnapshotEncodeOwner::new(native,grant);Ok::<_,ValueError>(owner.receive::<ProjectFrame,(),ProjectError>(&mut output,&mut |frame,_output,marker,unwind,native,body|{let before=native.actual_work();let result=(||{encoded_effect(native,body,marker,unwind,size_of::<Option<ProjectFrame>>(),1,||*frame=Some(ProjectFrame{value:None,allocation:Default::default()}))?;project_into(&source,frame.as_mut().unwrap(),native,body,marker,unwind)})();seen.set(frame.as_ref().is_some_and(|frame|partial(frame,text.len())));RetainedWorkOutcome{result,work:native.actual_work().checked_sub(before).unwrap()}}))}).unwrap()});
  assert!(armed.get());assert!(seen.get());assert!(turn.result.is_err());assert!(turn.work>0);reported.set(turn.work);assert!(output.is_none());assert_eq!(recipient.refused,deny);assert!(recipient.received.retained_capacity_bytes>=text.len());assert!(native.has_retirement_owner());assert_eq!(released,0);live.set(true);let(zero,allocated,released)=semio_framework_trace_memory_testing::observe_backing(||native.close_retirement_recipient(Default::default()).result);assert_eq!((allocated,released),(0,0));if let Ok(step)=zero{assert_eq!(step.progress(),Default::default())}assert!(native.has_retirement_owner());let mut total_born=born;let mut total_released=0;for _ in 0..100000{if !native.has_retirement_owner(){break}let(step,allocated,released)=semio_framework_trace_memory_testing::observe_backing(||native.close_retirement_recipient(grant).result.unwrap());assert!(step.progress().fits(grant));total_born+=allocated;total_released+=released;}assert!(!native.has_retirement_owner());assert_eq!(total_released,total_born);assert_eq!(source,original);Ok::<(),ValueError>(())
  }).unwrap();drop(work_loan);assert!(work.committed>=reported.get());

 }
}

#[test]
fn original_projection_recovers_allocation_after_funded_close_and_unwind(){
 use semio_framework_value::native_encoding::{NativeAllocationEvent,NativeEncodeAllocationPhase};
 use std::sync::atomic::{AtomicBool,AtomicUsize,Ordering};
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🪢️allocation-recovery/🔣️.json")).unwrap();let canonical=serde_json::to_string(&law).unwrap();assert_eq!(serde_json::from_str::<serde_json::Value>(&canonical).unwrap(),law);
 let grant=RetainedCloneGrant{maximum_items:10000,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<22,maximum_release_bytes:1<<22,maximum_depth:128};let target=2*size_of::<(String,DslValue)>();let fired=AtomicBool::new(false);let posts=AtomicUsize::new(0);let events=AtomicUsize::new(0);let mut port=|event:NativeAllocationEvent|{events.fetch_add(1,Ordering::SeqCst);if let NativeAllocationEvent::Post{request,..}=event{if request.bytes==target&&!fired.swap(true,Ordering::SeqCst){posts.fetch_add(1,Ordering::SeqCst);panic!("allocation post fixture unwind")}}Ok(())};let mut observer=|_|true;let mut retirement=NativeEncodeRetirementRecipient::new();let identity=retirement.identity();let mut allocation_issuer=semio_framework_value::native_encoding::NativeEncodeAllocationIssuer::new();let mut allocation_loan=allocation_issuer.loan(&mut port);let mut native=NativeEncodeControl::new_forwarded(grant.maximum_capacity_bytes,&mut observer,&mut allocation_loan);let wrong_events=AtomicUsize::new(0);let mut wrong_port=|_:NativeAllocationEvent|{wrong_events.fetch_add(1,Ordering::SeqCst);Ok(())};let mut wrong_issuer=semio_framework_value::native_encoding::NativeEncodeAllocationIssuer::new();let mut wrong_loan=wrong_issuer.loan(&mut wrong_port);let mut wrong_observer=|_|true;let mut wrong_native=NativeEncodeControl::new_forwarded(grant.maximum_capacity_bytes,&mut wrong_observer,&mut wrong_loan);native.install_retirement_recipient(&mut retirement).unwrap();let armed=Cell::new(false);let mut recipient=Recipient{grant,received:Default::default(),armed:&armed,deny:false,refused:false};let mut work=Work{remaining:1000000,committed:0};let mut work_issuer=semio_framework_value::native_encoding::NativeEncodeWorkIssuer::new();let mut work_loan=work_issuer.loan(&mut work);let mut construction_issuer=semio_framework_value::native_encoding::NativeEncodeConstructionIssuer::new();let mut construction_loan=construction_issuer.loan(&mut recipient);let source=SpaceHistorySnapshot::default();let mut output=None;
 let caught=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let _=native.with_work_recipient(&mut work_loan,|native|native.with_construction_recipient(&mut construction_loan,|native|{let mut owner=semio_framework_io_control::NativeSnapshotEncodeOwner::new(native,grant);Ok::<_,ValueError>(owner.receive::<ProjectFrame,(),ProjectError>(&mut output,&mut |frame,_output,marker,unwind,native,body|{let before=native.actual_work();let result=(||{encoded_effect(native,body,marker,unwind,size_of::<Option<ProjectFrame>>(),1,||*frame=Some(ProjectFrame{value:None,allocation:Default::default()}))?;project_into(&source,frame.as_mut().unwrap(),native,body,marker,unwind)})();RetainedWorkOutcome{result,work:native.actual_work().checked_sub(before).unwrap()}}))}));}));assert!(caught.is_err());assert!(native.has_retirement_owner());assert!(output.is_none());
 let mut wrong_issuer_calls=0usize;let mut wrong_type_calls=0usize;native.with_work_recipient(&mut work_loan,|native|native.with_construction_recipient(&mut construction_loan,|native|{
  let (blocked,born,released)=semio_framework_trace_memory_testing::observe_backing(||native.close_retirement_recipient(grant));let blocked_failure=match blocked.result{Err(error)=>error,Ok(_)=>panic!("unresolved allocation unexpectedly closed")};let _=(born,released);assert!(native.has_retirement_owner());
  let before=native.actual_work();let before_events=events.load(Ordering::SeqCst);let((wrong_issuer,wrong_type),born,released)=semio_framework_trace_memory_testing::observe_backing(||(native.visit_allocation_original::<ProjectFrame,()>(identity.wrapping_add(1),&mut |_,_|wrong_issuer_calls+=1),native.visit_allocation_original::<ProjectFrame,u8>(identity,&mut |_,_|wrong_type_calls+=1)));assert!(wrong_issuer.is_err());assert!(!wrong_type?);assert_eq!((born,released),(0,0));assert_eq!(native.actual_work(),before);assert_eq!(events.load(Ordering::SeqCst),before_events);assert_eq!(wrong_issuer_calls,law["wrongIssuerCalls"].as_u64().unwrap()as usize);assert_eq!(wrong_type_calls,law["wrongTypeCalls"].as_u64().unwrap()as usize);
  let mut visitor_panics=0usize;let visitor=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let _=native.visit_allocation_original::<ProjectFrame,()>(identity,&mut |_,_|{visitor_panics+=1;panic!("visitor fixture unwind")});}));assert!(visitor.is_err());assert_eq!(visitor_panics,law["visitorPanics"].as_u64().unwrap()as usize);assert!(native.has_retirement_owner());
  let recovered=native.visit_allocation_original::<ProjectFrame,()>(identity,&mut |frame,recovery|{let frame=frame.as_mut().unwrap();let actual=frame.allocation.actual;let progress=frame.allocation.unwind.as_mut().unwrap();assert_eq!(progress.forwarded_phase(),NativeEncodeAllocationPhase::SettlementStarted);recovery.resolve_forwarded_allocation_callback(progress,Ok(())).unwrap();assert!(wrong_native.settle_allocation_progress(progress,actual).is_err());assert_eq!(wrong_events.load(Ordering::SeqCst),law["wrongLoanEvents"].as_u64().unwrap()as usize);recovery.settle_allocation_progress(progress,actual).unwrap();let progress=frame.allocation.unwind.take().unwrap();let expected=progress.request().bytes;let outcome=match progress.into_outcome(){Ok(outcome)=>outcome,Err(progress)=>{frame.allocation.unwind=Some(progress);panic!("allocation remained unsettled")}};assert!(frame.allocation.capture(outcome,expected).unwrap());})?;assert!(recovered);
  for _ in 0..100000{if !native.has_retirement_owner(){break}let turn=native.close_retirement_recipient(grant);assert!(turn.result.is_ok())}assert!(!native.has_retirement_owner());let mut failure=semio_framework_value::retirement::controlled::ControlledRetirement::new(blocked_failure).ok().unwrap();for _ in 0..4096{if failure.terminal_is_empty(){break}failure.step(grant).unwrap();}assert!(failure.terminal_is_empty());Ok::<_,ValueError>(())
 })).unwrap();assert_eq!(posts.load(Ordering::SeqCst),law["postAttempts"].as_u64().unwrap()as usize);
}
